SampleRun.Run<object[]>(async () =>
{
    await using var app = await AuthApp.StartAsync();

    for (var i = 0; i < 5; i++)
        await app.PostAsync("login", new { identifier = "radman", secret = "wrong" });

    var sixth = await app.PostAsync("login", new { identifier = "radman", secret = "right-pass" });

    return [$"sixth answer: {SampleRun.Status(sixth)}", $"Retry-After: {sixth.Headers.RetryAfter?.Delta?.TotalSeconds} seconds"];
});

SampleRun.Run<object[]>(async () =>
{
    await using var app = await AuthApp.StartAsync();

    var (token, _) = await app.SignInAsync();

    var before = await app.GetAsync("access", token);
    await app.PostAsync("logout", token: token);
    var after = await app.GetAsync("access", token);

    return [$"before logout: {SampleRun.Status(before)}", $"after logout: {SampleRun.Status(after)}"];
});

