SampleRun.Run<object[]>(async () =>
{
    await using var app = await TestApp.StartAsync();
    await using var scope = app.App.Services.CreateAsyncScope();

    var sessions = scope.ServiceProvider.GetRequiredService<ISessionStore>();
    var opened = await sessions.OpenAsync(7);

    var before = await app.GetAsync("/me", user: 7, session: opened.Id);

    await sessions.RevokeAsync(opened.Id, IdentityCodes.SessionReason.AdminRevoked);

    var after = await app.GetAsync("/me", user: 7, session: opened.Id);

    return [$"before the revoke: {SampleRun.Status(before)}", $"after the revoke: {SampleRun.Status(after)}"];
});

